create type public.etl_run_status as enum ('pending','running','staged','completed','failed');
create type public.merdp_finding_severity as enum ('info','warning','quarantine','reject');
create type public.merdp_review_status as enum ('open','in_review','resolved','dismissed');
create type public.merdp_resolution_outcome as enum ('exact_match','probable_match','renewal_or_version','variant','identifier_collision','distinct','unresolved');
create type public.merdp_certification_status as enum ('ingested','normalized','resolved','certified','published','revoked');
create table public.etl_sources(id uuid primary key default gen_random_uuid(),source_code text not null unique,authority text not null,name text not null,description text,configuration jsonb not null default '{}',enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.etl_snapshots(id uuid primary key default gen_random_uuid(),source_id uuid not null references public.etl_sources(id),artifact_name text not null,artifact_uri text not null,sha256 text not null check(sha256~'^[0-9a-f]{64}$'),byte_size bigint not null,schema_fingerprint text not null,row_count integer not null,column_count integer not null,extracted_at timestamptz,received_at timestamptz not null default now(),metadata jsonb not null default '{}',unique(source_id,sha256));
create table public.etl_runs(id uuid primary key default gen_random_uuid(),source_id uuid not null references public.etl_sources(id),snapshot_id uuid not null references public.etl_snapshots(id),status public.etl_run_status not null default 'pending',started_at timestamptz,completed_at timestamptz,rows_read integer not null default 0,rows_valid integer not null default 0,rows_warning integer not null default 0,rows_quarantined integer not null default 0,rows_rejected integer not null default 0,rows_staged integer not null default 0,checkpoint jsonb,error_summary jsonb,metrics jsonb not null default '{}');
create table public.etl_source_records(id uuid primary key default gen_random_uuid(),source_id uuid not null references public.etl_sources(id),snapshot_id uuid not null references public.etl_snapshots(id),run_id uuid not null references public.etl_runs(id),source_record_id text not null,schema_version text not null,raw_payload jsonb not null,raw_payload_sha256 text not null,created_at timestamptz not null default now(),unique(source_id,snapshot_id,source_record_id));
create or replace function public.prevent_etl_source_record_mutation() returns trigger language plpgsql set search_path='' as $$ begin raise exception 'raw ETL source records are immutable'; end; $$;
create trigger etl_source_records_immutable before update or delete on public.etl_source_records for each row execute function public.prevent_etl_source_record_mutation();
create table public.merdp_quality_findings(id uuid primary key default gen_random_uuid(),run_id uuid not null references public.etl_runs(id),source_record_id uuid references public.etl_source_records(id),rule_code text not null,field_name text,raw_value text,severity public.merdp_finding_severity not null,message text not null,resolution_status public.merdp_review_status not null default 'open',created_at timestamptz not null default now(),unique(run_id,source_record_id,rule_code,field_name));
create table public.merdp_source_mappings(id uuid primary key default gen_random_uuid(),source_record_id uuid not null unique references public.etl_source_records(id),canonical_product_id uuid references public.medicines(id),canonical_organization_id uuid references public.organizations(id),regulatory_identifier text,resolution public.merdp_resolution_outcome not null,evidence jsonb not null,created_at timestamptz not null default now());
create table public.merdp_normalized_values(id uuid primary key default gen_random_uuid(),source_record_id uuid not null references public.etl_source_records(id),attribute_name text not null,raw_value text,normalized_value text,rule_version text not null,confidence numeric(5,4),created_at timestamptz not null default now(),unique(source_record_id,attribute_name,rule_version));
create table public.merdp_review_cases(id uuid primary key default gen_random_uuid(),reason_code text not null,status public.merdp_review_status not null default 'open',evidence jsonb not null,candidate_entities jsonb not null default '[]',resolution jsonb,resolver_id uuid references auth.users(id),resolved_at timestamptz,created_at timestamptz not null default now());
create table public.merdp_provenance(id uuid primary key default gen_random_uuid(),canonical_product_id uuid references public.medicines(id),canonical_organization_id uuid references public.organizations(id),attribute_name text not null,winning_value jsonb not null,winning_source_record_id uuid not null references public.etl_source_records(id),rule_version text not null,candidate_values jsonb not null default '[]',effective_at timestamptz not null default now(),check(canonical_product_id is not null or canonical_organization_id is not null));
create table public.merdp_certifications(id uuid primary key default gen_random_uuid(),canonical_product_id uuid not null references public.medicines(id),status public.merdp_certification_status not null,policy_version text not null,evidence jsonb not null,certified_by uuid references auth.users(id),certified_at timestamptz,unique(canonical_product_id,policy_version));
create table public.merdp_publications(id uuid primary key default gen_random_uuid(),canonical_product_id uuid not null references public.medicines(id),certification_id uuid not null references public.merdp_certifications(id),version integer not null,projection jsonb not null,provenance_manifest jsonb not null,published_at timestamptz not null default now(),unique(canonical_product_id,version));
create table public.merdp_manufacturer_source_links(id uuid primary key default gen_random_uuid(),source_record_id uuid not null references public.etl_source_records(id),source_manufacturer_id text not null,canonical_organization_id uuid references public.organizations(id),resolution public.merdp_resolution_outcome not null,evidence jsonb not null,unique(source_record_id,source_manufacturer_id));
create index etl_source_records_identity_idx on public.etl_source_records(source_id,source_record_id); create index merdp_mappings_regulatory_idx on public.merdp_source_mappings(regulatory_identifier) where regulatory_identifier is not null;
alter table public.etl_sources enable row level security; alter table public.etl_snapshots enable row level security; alter table public.etl_runs enable row level security; alter table public.etl_source_records enable row level security; alter table public.merdp_quality_findings enable row level security; alter table public.merdp_source_mappings enable row level security; alter table public.merdp_normalized_values enable row level security; alter table public.merdp_review_cases enable row level security; alter table public.merdp_provenance enable row level security; alter table public.merdp_certifications enable row level security; alter table public.merdp_publications enable row level security; alter table public.merdp_manufacturer_source_links enable row level security;
grant select,insert,update on public.etl_sources,public.etl_snapshots,public.etl_runs to service_role;
grant select,insert on public.etl_source_records,public.merdp_quality_findings,public.merdp_source_mappings,public.merdp_normalized_values,public.merdp_review_cases,public.merdp_provenance,public.merdp_certifications,public.merdp_publications,public.merdp_manufacturer_source_links to service_role;
